begin;
with j as (select * from jsonb_to_recordset($law7d0047$[{"code_id":"KONST_RF","article_number":"70","version_date":"1993-12-12","article_text":"1.Государственные флаг, герб и гимн Российской Федерации, их описание и порядок официального использования устанавливаются федеральным конституционным законом.\n\n2.Столицей Российской Федерации является город Москва. Статус столицы устанавливается федеральным законом. Местом постоянного пребывания отдельных федеральных органов государственной власти может быть другой город, определенный федеральным конституционным законом.","article_title":"Статья 70","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"17006021c5776119b8b223e02e34e49670b5e03ca3e021dcc3e1a724e03aae66"},{"code_id":"KONST_RF","article_number":"71","version_date":"1993-12-12","article_text":"В ведении Российской Федерации находятся:\n\nа)принятие и изменение Конституции Российской Федерации и федеральных законов, контроль за их соблюдением;\n\nб)федеративное устройство и территория Российской Федерации;\n\nв)регулирование и защита прав и свобод человека и гражданина; гражданство в Российской Федерации; регулирование и защита прав национальных меньшинств;\n\nг)организация публичной власти; установление системы федеральных органов законодательной, исполнительной и судебной власти, порядка их организации и деятельности; формирование федеральных органов государственной власти;*\n\nд)федеральная государственная собственность и управление ею;\n\nе)установление основ федеральной политики и федеральные программы в области государственного, экономического, экологического, научно-технологического, социального, культурного и национального развития Российской Федерации; установление единых правовых основ системы здравоохранения, системы воспитания и образования, в том числе непрерывного образования;*\n\nж)установление правовых основ единого рынка; финансовое, валютное, кредитное, таможенное регулирование, денежная эмиссия, основы ценовой политики; федеральные экономические службы, включая федеральные банки;\n\nз)федеральный бюджет; федеральные налоги и сборы; федеральные фонды регионального развития;\n\nи)федеральные энергетические системы, ядерная энергетика, расщепляющиеся материалы; федеральные транспорт, пути сообщения, информация, информационные технологии и связь; космическая деятельность;*\n\nк)внешняя политика и международные отношения Российской Федерации, международные договоры Российской Федерации; вопросы войны и мира;\n\nл)внешнеэкономические отношения Российской Федерации;\n\nм)оборона и безопасность; оборонное производство; определение порядка продажи и покупки оружия, боеприпасов, военной техники и другого военного имущества; производство ядовитых веществ, наркотических средств и порядок их использования; обеспечение безопасности личности, общества и государства при применении информационных технологий, обороте цифровых данных;*\n\nн)определение статуса и защита государственной границы, территориального моря, воздушного пространства, исключительной экономической зоны и континентального шельфа Российской Федерации;\n\nо)судоустройство; прокуратура; уголовное и уголовно-исполнительное законодательство; амнистия и помилование; гражданское законодательство; процессуальное законодательство; правовое регулирование интеллектуальной собственности;\n\nРедакция пункта «о» приведена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 5 февраля 2014 г. № 2-ФКЗ «О Верховном Суде Российской Федерации и прокуратуре Российской Федерации», вступившим в силу со дня его официального опубликования 6 февраля 2014 г. (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2014, 6 февраля, № 0001201402060001).\n\nп)федеральное коллизионное право;\n\nр)метрологическая служба, стандарты, эталоны, метрическая система и исчисление времени; геодезия и картография; наименования географических объектов; метеорологическая служба; официальный статистический и бухгалтерский учет;*\n\nс)государственные награды и почетные звания Российской Федерации;\n\nт)федеральная государственная служба; установление ограничений для замещения государственных и муниципальных должностей, должностей государственной и муниципальной службы, в том числе ограничений, связанных с наличием гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства, а также ограничений, связанных с открытием и наличием счетов (вкладов), хранением наличных денежных средств и ценностей в иностранных банках, расположенных за пределами территории Российской Федерации.*","article_title":"Статья 71","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"67233c4ae9a399a70c5c8302d10a15930285c1565c5830baabd9d12f40b27e22"},{"code_id":"KONST_RF","article_number":"72","version_date":"1993-12-12","article_text":"1.В совместном ведении Российской Федерации и субъектов Российской Федерации находятся:\n\nа)обеспечение соответствия конституций и законов республик, уставов, законов и иных нормативных правовых актов краев, областей, городов федерального значения, автономной области, автономных округов Конституции Российской Федерации и федеральным законам;\n\nб)защита прав и свобод человека и гражданина; защита прав национальных меньшинств; обеспечение законности, правопорядка, общественной безопасности; режим пограничных зон;\n\nв)вопросы владения, пользования и распоряжения землей, недрами, водными и другими природными ресурсами;\n\nг)разграничение государственной собственности;\n\nд)природопользование; сельское хозяйство; охрана окружающей среды и обеспечение экологической безопасности; особо охраняемые природные территории; охрана памятников истории и культуры;*\n\nе)общие вопросы воспитания, образования, науки, культуры, физической культуры и спорта, молодежной политики;*\n\nж)координация вопросов здравоохранения, в том числе обеспечение оказания доступной и качественной медицинской помощи, сохранение и укрепление общественного здоровья, создание условий для ведения здорового образа жизни, формирования культуры ответственного отношения граждан к своему здоровью; социальная защита, включая социальное обеспечение;*\n\nж1)защита семьи, материнства, отцовства и детства; защита института брака как союза мужчины и женщины; создание условий для достойного воспитания детей в семье, а также для осуществления совершеннолетними детьми обязанности заботиться о родителях;*\n\nз)осуществление мер по борьбе с катастрофами, стихийными бедствиями, эпидемиями, ликвидация их последствий;\n\nи)установление общих принципов налогообложения и сборов в Российской Федерации;\n\nк)административное, административно-процессуальное, трудовое, семейное, жилищное, земельное, водное, лесное законодательство, законодательство о недрах, об охране окружающей среды;\n\nл)кадры судебных и правоохранительных органов; адвокатура, нотариат;\n\nм)защита исконной среды обитания и традиционного образа жизни малочисленных этнических общностей;\n\nн)установление общих принципов организации системы органов государственной власти и местного самоуправления;\n\nо)координация международных и внешнеэкономических связей субъектов Российской Федерации, выполнение международных договоров Российской Федерации.\n\n2.Положения настоящей статьи в равной мере распространяются на республики, края, области, города федерального значения, автономную область, автономные округа.","article_title":"Статья 72","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c61a77d70076a259faa72caa959762b0f08524ad6100d498ac7229c010c3bf72"},{"code_id":"KONST_RF","article_number":"73","version_date":"1993-12-12","article_text":"Вне пределов ведения Российской Федерации и полномочий Российской Федерации по предметам совместного ведения Российской Федерации и субъектов Российской Федерации субъекты Российской Федерации обладают всей полнотой государственной власти.","article_title":"Статья 73","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1b8a8779b48de1876ed20590fa1f1045894378aac7ba486cacfce14fd71c4663"},{"code_id":"KONST_RF","article_number":"74","version_date":"1993-12-12","article_text":"1.На территории Российской Федерации не допускается установление таможенных границ, пошлин, сборов и каких-либо иных препятствий для свободного перемещения товаров, услуг и финансовых средств.\n\n2.Ограничения перемещения товаров и услуг могут вводиться в соответствии с федеральным законом, если это необходимо для обеспечения безопасности, защиты жизни и здоровья людей, охраны природы и культурных ценностей.","article_title":"Статья 74","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0a2cb5b3c8983cfa3b9b9eb3871afc75cce482a5c573f4444301c44f1d5a17a"},{"code_id":"KONST_RF","article_number":"75","version_date":"1993-12-12","article_text":"1.Денежной единицей в Российской Федерации является рубль. Денежная эмиссия осуществляется исключительно Центральным банком Российской Федерации. Введение и эмиссия других денег в Российской Федерации не допускаются.\n\n2.Защита и обеспечение устойчивости рубля — основная функция Центрального банка Российской Федерации, которую он осуществляет независимо от других органов государственной власти.\n\n3.Система налогов, взимаемых в федеральный бюджет, и общие принципы налогообложения и сборов в Российской Федерации устанавливаются федеральным законом.\n\n4.Государственные займы выпускаются в порядке, определяемом федеральным законом, и размещаются на добровольной основе.\n\n5.Российская Федерация уважает труд граждан и обеспечивает защиту их прав. Государством гарантируется минимальный размер оплаты труда не менее величины прожиточного минимума трудоспособного населения в целом по Российской Федерации.\n\n6.В Российской Федерации формируется система пенсионного обеспечения граждан на основе принципов всеобщности, справедливости и солидарности поколений и поддерживается ее эффективное функционирование, а также осуществляется индексация пенсий не реже одного раза в год в порядке, установленном федеральным законом.\n\n7.В Российской Федерации в соответствии с федеральным законом гарантируются обязательное социальное страхование, адресная социальная поддержка граждан и индексация социальных пособий и иных социальных выплат.","article_title":"Статья 75","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"59042b9cd92971358f67d3ef0c68327306b71fae9017f53705f67d5859636827"},{"code_id":"KONST_RF","article_number":"76","version_date":"1993-12-12","article_text":"1.По предметам ведения Российской Федерации принимаются федеральные конституционные законы и федеральные законы, имеющие прямое действие на всей территории Российской Федерации.\n\n2.По предметам совместного ведения Российской Федерации и субъектов Российской Федерации издаются федеральные законы и принимаемые в соответствии с ними законы и иные нормативные правовые акты субъектов Российской Федерации.\n\n3.Федеральные законы не могут противоречить федеральным конституционным законам.\n\n4.Вне пределов ведения Российской Федерации, совместного ведения Российской Федерации и субъектов Российской Федерации республики, края, области, города федерального значения, автономная область и автономные округа осуществляют собственное правовое регулирование, включая принятие законов и иных нормативных правовых актов.\n\n5.Законы и иные нормативные правовые акты субъектов Российской Федерации не могут противоречить федеральным законам, принятым в соответствии с частями первой и второй настоящей статьи. В случае противоречия между федеральным законом и иным актом, изданным в Российской Федерации, действует федеральный закон.\n\n6.В случае противоречия между федеральным законом и нормативным правовым актом субъекта Российской Федерации, изданным в соответствии с частью четвертой настоящей статьи, действует нормативный правовой акт субъекта Российской Федерации.","article_title":"Статья 76","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4faf867df5ad90066ae70b82cf7a0d4881ed292b3d1cfed64ec6b7ba791c62ed"},{"code_id":"KONST_RF","article_number":"77","version_date":"1993-12-12","article_text":"1.Система органов государственной власти республик, краев, областей, городов федерального значения, автономной области, автономных округов устанавливается субъектами Российской Федерации самостоятельно в соответствии с основами конституционного строя Российской Федерации и общими принципами организации представительных и исполнительных органов государственной власти, установленными федеральным законом.\n\n2.В пределах ведения Российской Федерации и полномочий Российской Федерации по предметам совместного ведения Российской Федерации и субъектов Российской Федерации федеральные органы исполнительной власти и органы исполнительной власти субъектов Российской Федерации образуют единую систему исполнительной власти в Российской Федерации.\n\n3.Высшим должностным лицом субъекта Российской Федерации (руководителем высшего исполнительного органа государственной власти субъекта Российской Федерации) может быть гражданин Российской Федерации, достигший 30 лет, постоянно проживающий в Российской Федерации, не имеющий гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Высшему должностному лицу субъекта Российской Федерации (руководителю высшего исполнительного органа государственной власти субъекта Российской Федерации) в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации. Федеральным законом могут быть установлены дополнительные требования к высшему должностному лицу субъекта Российской Федерации (руководителю высшего исполнительного органа государственной власти субъекта Российской Федерации).*","article_title":"Статья 77","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3398103d0c4c85e0665e98532b30e79014b958c86bc85805d9043b35b84434c2"},{"code_id":"KONST_RF","article_number":"78","version_date":"1993-12-12","article_text":"1.Федеральные органы исполнительной власти для осуществления своих полномочий могут создавать свои территориальные органы и назначать соответствующих должностных лиц.\n\n2.Федеральные органы исполнительной власти по соглашению с органами исполнительной власти субъектов Российской Федерации могут передавать им осуществление части своих полномочий, если это не противоречит Конституции Российской Федерации и федеральным законам.\n\n3.Органы исполнительной власти субъектов Российской Федерации по соглашению с федеральными органами исполнительной власти могут передавать им осуществление части своих полномочий.\n\n4.Президент Российской Федерации и Правительство Российской Федерации обеспечивают в соответствии с Конституцией Российской Федерации осуществление полномочий федеральной государственной власти на всей территории Российской Федерации.\n\n5.Руководителем федерального государственного органа может быть гражданин Российской Федерации, достигший 30 лет, не имеющий гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Руководителю федерального государственного органа в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации.*","article_title":"Статья 78","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d573e2d7517d968da84a41b80e420c274b6e76486a4b1f5e17a7e7a197e734df"},{"code_id":"KONST_RF","article_number":"79","version_date":"1993-12-12","article_text":"Российская Федерация может участвовать в межгосударственных объединениях и передавать им часть своих полномочий в соответствии с международными договорами Российской Федерации, если это не влечет за собой ограничения прав и свобод человека и гражданина и не противоречит основам конституционного строя Российской Федерации. Решения межгосударственных органов, принятые на основании положений международных договоров Российской Федерации в их истолковании, противоречащем Конституции Российской Федерации, не подлежат исполнению в Российской Федерации.","article_title":"Статья 79","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"095df6da05942c6f174c0c5f6f60c7146456ca6cc0e5aa63bf6e4a618f0e3e31"},{"code_id":"KONST_RF","article_number":"8","version_date":"1993-12-12","article_text":"1.В Российской Федерации гарантируются единство экономического пространства, свободное перемещение товаров, услуг и финансовых средств, поддержка конкуренции, свобода экономической деятельности.\n\n2.В Российской Федерации признаются и защищаются равным образом частная, государственная, муниципальная и иные формы собственности.","article_title":"Статья 8","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8b7b598b6adec35ff639bd1f64cfe5273ddc0bd10e02156745c58f897b5be66"},{"code_id":"KONST_RF","article_number":"80","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации является главой государства.\n\n2.Президент Российской Федерации является гарантом Конституции Российской Федерации, прав и свобод человека и гражданина. В установленном Конституцией Российской Федерации порядке он принимает меры по охране суверенитета Российской Федерации, ее независимости и государственной целостности, поддерживает гражданский мир и согласие в стране, обеспечивает согласованное функционирование и взаимодействие органов, входящих в единую систему публичной власти.*\n\n3.Президент Российской Федерации в соответствии с Конституцией Российской Федерации и федеральными законами определяет основные направления внутренней и внешней политики государства.\n\n4.Президент Российской Федерации как глава государства представляет Российскую Федерацию внутри страны и в международных отношениях.","article_title":"Статья 80","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"49975cd74b7f2177640434d6a894372c8290e8374e905788436b83f8d930dca5"},{"code_id":"KONST_RF","article_number":"81","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации избирается сроком на шесть лет гражданами Российской Федерации на основе всеобщего равного и прямого избирательного права при тайном голосовании.\n\nРедакция части 1 приведена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 30 декабря 2008 г. № 6-ФКЗ«Об изменении срока полномочий Президента Российской Федерации и Государственной Думы», вступившим в силу со дня его официального опубликования 31 декабря 2008 г.(Российская газета, 2008, 31 декабря). Применяется в отношении Президента Российской Федерации, избранного после вступления в силу названного Закона.\n\n2.Президентом Российской Федерации может быть избран гражданин Российской Федерации не моложе 35 лет, постоянно проживающий в Российской Федерации не менее 25 лет, не имеющий и не имевший ранее гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Требование к кандидату на должность Президента Российской Федерации об отсутствии у него гражданства иностранного государства не распространяется на граждан Российской Федерации, ранее имевших гражданство государства, которое было принято или часть которого была принята в Российскую Федерацию в соответствии с федеральным конституционным законом, и постоянно проживавших на территории принятого в Российскую Федерацию государства или территории принятой в Российскую Федерацию части государства. Президенту Российской Федерации в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации.\n\n3.Одно и то же лицо не может занимать должность Президента Российской Федерации более двух сроков.\n\n31.Положение части 3 статьи 81 Конституции Российской Федерации, ограничивающее число сроков, в течение которых одно и то же лицо может занимать должность Президента Российской Федерации, применяется к лицу, занимавшему и (или) занимающему должность Президента Российской Федерации, без учета числа сроков, в течение которых оно занимало и (или) занимает эту должность на момент вступления в силу поправки к Конституции Российской Федерации, вносящей соответствующее ограничение, и не исключает для него возможность занимать должность Президента Российской Федерации в течение сроков, допустимых указанным положением.\n\n4.Порядок выборов Президента Российской Федерации определяется федеральным законом.","article_title":"Статья 81","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"892a6107ae96e11ee98d499fc55a1c4409b7df58fc048892751286b100ceb53b"},{"code_id":"KONST_RF","article_number":"82","version_date":"1993-12-12","article_text":"1.При вступлении в должность Президент Российской Федерации приносит народу следующую присягу:\n\n«Клянусь при осуществлении полномочий Президента Российской Федерации уважать и охранять права и свободы человека и гражданина, соблюдать и защищать Конституцию Российской Федерации, защищать суверенитет и независимость, безопасность и целостность государства, верно служить народу».\n\n2.Присяга приносится в торжественной обстановке в присутствии сенаторов Российской Федерации, депутатов Государственной Думы и судей Конституционного Суда Российской Федерации.*","article_title":"Статья 82","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"69b59ad2b260046fa31c989d6d000c573e76d815607a64841fecb0a6a280458f"},{"code_id":"KONST_RF","article_number":"83","version_date":"1993-12-12","article_text":"Президент Российской Федерации:\n\nа)назначает Председателя Правительства Российской Федерации, кандидатура которого утверждена Государственной Думой по представлению Президента Российской Федерации, и освобождает Председателя Правительства Российской Федерации от должности;*\n\nб)осуществляет общее руководство Правительством Российской Федерации; вправе председательствовать на заседаниях Правительства Российской Федерации;*\n\nб1)утверждает по предложению Председателя Правительства Российской Федерации структуру федеральных органов исполнительной власти, вносит в нее изменения; в структуре федеральных органов исполнительной власти определяет органы, руководство деятельностью которых осуществляет Президент Российской Федерации, и органы, руководство деятельностью которых осуществляет Правительство Российской Федерации. В случае если Председатель Правительства Российской Федерации освобожден Президентом Российской Федерации от должности, вновь назначенный Председатель Правительства Российской Федерации не представляет Президенту Российской Федерации предложения о структуре федеральных органов исполнительной власти;*\n\nв)принимает решение об отставке Правительства Российской Федерации;\n\nв1)принимает отставку Председателя Правительства Российской Федерации, заместителей Председателя Правительства Российской Федерации, федеральных министров, а также руководителей федеральных органов исполнительной власти, руководство деятельностью которых осуществляет Президент Российской Федерации;*\n\nг)представляет Государственной Думе кандидатуру для назначения на должность Председателя Центрального банка Российской Федерации; ставит перед Государственной Думой вопрос об освобождении от должности Председателя Центрального банка Российской Федерации;\n\nд)назначает на должность заместителей Председателя Правительства Российской Федерации и федеральных министров, кандидатуры которых утверждены Государственной Думой (за исключением федеральных министров, указанных в пункте «д1» настоящей статьи), и освобождает их от должности;*\n\nд1)назначает на должность после консультаций с Советом Федерации и освобождает от должности руководителей федеральных органов исполнительной власти (включая федеральных министров), ведающих вопросами обороны, безопасности государства, внутренних дел, юстиции, иностранных дел, предотвращения чрезвычайных ситуаций и ликвидации последствий стихийных бедствий, общественной безопасности;*\n\nе)представляет Совету Федерации кандидатуры для назначения на должность Председателя Конституционного Суда Российской Федерации, заместителя Председателя Конституционного Суда Российской Федерации и судей Конституционного Суда Российской Федерации, Председателя Верховного Суда Российской Федерации, заместителей Председателя Верховного Суда Российской Федерации и судей Верховного Суда Российской Федерации; назначает председателей, заместителей председателей и судей других федеральных судов;*\n\nе1)назначает на должность после консультаций с Советом Федерации и освобождает от должности Генерального прокурора Российской Федерации, заместителей Генерального прокурора Российской Федерации, прокуроров субъектов Российской Федерации, прокуроров военных и других специализированных прокуратур, приравненных к прокурорам субъектов Российской Федерации; назначает на должность и освобождает от должности иных прокуроров, для которых такой порядок назначения и освобождения от должности установлен федеральным законом;*\n\nе2)назначает и освобождает представителей Российской Федерации в Совете Федерации;\n\nСтатья 83 дополнена пунктом «е2» в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 21 июля 2014 г. № 11-ФКЗ «О Совете Федерации Федерального Собрания Российской Федерации», вступившим в силу со дня его официального опубликования 22 июля 2014 г. (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2014, 22 июля, № 0001201407220002).\n\nе3)вносит в Совет Федерации представление о прекращении в соответствии с федеральным конституционным законом полномочий Председателя Конституционного Суда Российской Федерации, заместителя Председателя Конституционного Суда Российской Федерации и судей Конституционного Суда Российской Федерации, Председателя Верховного Суда Российской Федерации, заместителей Председателя Верховного Суда Российской Федерации и судей Верховного Суда Российской Федерации, председателей, заместителей председателей и судей кассационных и апелляционных судов в случае совершения ими поступка, порочащего честь и достоинство судьи, а также в иных предусмотренных федеральным конституционным законом случаях, свидетельствующих о невозможности осуществления судьей своих полномочий;*\n\nе4)представляет Совету Федерации кандидатуры для назначения на должность Председателя Счетной палаты и половины от общего числа аудиторов Счетной палаты; представляет Государственной Думе кандидатуры для назначения на должность заместителя Председателя Счетной палаты и половины от общего числа аудиторов Счетной палаты;*\n\nе5)формирует Государственный Совет Российской Федерации в целях обеспечения согласованного функционирования и взаимодействия органов публичной власти, определения основных направлений внутренней и внешней политики Российской Федерации и приоритетных направлений социально-экономического развития государства; статус Государственного Совета Российской Федерации определяется федеральным законом;*\n\nж)формирует Совет Безопасности Российской Федерации в целях содействия главе государства в реализации его полномочий по вопросам обеспечения национальных интересов и безопасности личности, общества и государства, а также поддержания гражданского мира и согласия в стране, охраны суверенитета Российской Федерации, ее независимости и государственной целостности, предотвращения внутренних и внешних угроз; возглавляет Совет Безопасности Российской Федерации. Статус Совета Безопасности Российской Федерации определяется федеральным законом;*\n\nз)утверждает военную доктрину Российской Федерации;\n\nи)формирует Администрацию Президента Российской Федерации в целях обеспечения реализации своих полномочий;*\n\nк)назначает и освобождает полномочных представителей Президента Российской Федерации;\n\nл)назначает и освобождает высшее командование Вооруженных Сил Российской Федерации;\n\nм)назначает и отзывает после консультаций с соответствующими комитетами или комиссиями палат Федерального Собрания дипломатических представителей Российской Федерации в иностранных государствах и международных организациях.","article_title":"Статья 83","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5432e1b08cb5a304b27f90dbc24d6a349010c88221ceaaef936b8f153b1e708c"},{"code_id":"KONST_RF","article_number":"84","version_date":"1993-12-12","article_text":"Президент Российской Федерации:\n\nа)назначает выборы Государственной Думы в соответствии с Конституцией Российской Федерации и федеральным законом;\n\nб)распускает Государственную Думу в случаях и порядке, предусмотренных Конституцией Российской Федерации;\n\nв)назначает референдум в порядке, установленном федеральным конституционным законом;\n\nг)вносит законопроекты в Государственную Думу;\n\nд)подписывает и обнародует федеральные законы;\n\nе)обращается к Федеральному Собранию с ежегодными посланиями о положении в стране, об основных направлениях внутренней и внешней политики государства.","article_title":"Статья 84","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd47dfe61b942c65de703a3a17725ebd345791316932f45bd8bccfcdc3b80bbe"},{"code_id":"KONST_RF","article_number":"85","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации может использовать согласительные процедуры для разрешения разногласий между органами государственной власти Российской Федерации и органами государственной власти субъектов Российской Федерации, а также между органами государственной власти субъектов Российской Федерации. В случае недостижения согласованного решения он может передать разрешение спора на рассмотрение соответствующего суда.\n\n2.Президент Российской Федерации вправе приостанавливать действие актов органов исполнительной власти субъектов Российской Федерации в случае противоречия этих актов Конституции Российской Федерации и федеральным законам, международным обязательствам Российской Федерации или нарушения прав и свобод человека и гражданина до решения этого вопроса соответствующим судом.","article_title":"Статья 85","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cec22e46f9daf7d503f835bec3d9f0ac9bb17472f72bd2267dab692a46089704"},{"code_id":"KONST_RF","article_number":"86","version_date":"1993-12-12","article_text":"Президент Российской Федерации:\n\nа)осуществляет руководство внешней политикой Российской Федерации;\n\nб)ведет переговоры и подписывает международные договоры Российской Федерации;\n\nв)подписывает ратификационные грамоты;\n\nг)принимает верительные и отзывные грамоты аккредитуемых при нем дипломатических представителей.","article_title":"Статья 86","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"68884727b05857c5f58ee7bf071d9ab4bcb9275b64a306c976bca3481d960ad7"},{"code_id":"KONST_RF","article_number":"87","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации является Верховным Главнокомандующим Вооруженными Силами Российской Федерации.\n\n2.В случае агрессии против Российской Федерации или непосредственной угрозы агрессии Президент Российской Федерации вводит на территории Российской Федерации или в отдельных ее местностях военное положение с незамедлительным сообщением об этом Совету Федерации и Государственной Думе.\n\n3.Режим военного положения определяется федеральным конституционным законом.","article_title":"Статья 87","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a101f3775f989706c3192968201b8a95f2e1d17af9d27e9827c448f6f6da63e8"},{"code_id":"KONST_RF","article_number":"88","version_date":"1993-12-12","article_text":"Президент Российской Федерации при обстоятельствах и в порядке, предусмотренных федеральным конституционным законом, вводит на территории Российской Федерации или в отдельных ее местностях чрезвычайное положение с незамедлительным сообщением об этом Совету Федерации и Государственной Думе.","article_title":"Статья 88","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"590cab13b9bac7cb5ca95bd6cd3ce913b12aafe207fb3b93d283b7a491f2e4fb"},{"code_id":"KONST_RF","article_number":"89","version_date":"1993-12-12","article_text":"Президент Российской Федерации:\n\nа)решает вопросы гражданства Российской Федерации и предоставления политического убежища;\n\nб)награждает государственными наградами Российской Федерации, присваивает почетные звания Российской Федерации, высшие воинские и высшие специальные звания;\n\nв)осуществляет помилование.","article_title":"Статья 89","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7d5908353bb7c35e7aaeadabb10d0e0228cb7dae1541be31febc0d77c907f1ec"},{"code_id":"KONST_RF","article_number":"9","version_date":"1993-12-12","article_text":"1.Земля и другие природные ресурсы используются и охраняются в Российской Федерации как основа жизни и деятельности народов, проживающих на соответствующей территории.\n\n2.Земля и другие природные ресурсы могут находиться в частной, государственной, муниципальной и иных формах собственности.","article_title":"Статья 9","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"056bd137c38bf8a625aab3218ac484801cd102f9d10a2d4d3399b56a9fa52908"},{"code_id":"KONST_RF","article_number":"90","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации издает указы и распоряжения.\n\n2.Указы и распоряжения Президента Российской Федерации обязательны для исполнения на всей территории Российской Федерации.\n\n3.Указы и распоряжения Президента Российской Федерации не должны противоречить Конституции Российской Федерации и федеральным законам.","article_title":"Статья 90","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"375b1e9028e78d99474fbbd745a76627b4a67087fb305f5557394d40ac39a9d1"},{"code_id":"KONST_RF","article_number":"91","version_date":"1993-12-12","article_text":"Президент Российской Федерации обладает неприкосновенностью.","article_title":"Статья 91","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1e90750ca3811401df948cba2f60a9a255cbb97217213e7a543d48875d41b9f1"},{"code_id":"KONST_RF","article_number":"92","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации приступает к исполнению полномочий с момента принесения им присяги и прекращает их исполнение с истечением срока его пребывания в должности с момента принесения присяги вновь избранным Президентом Российской Федерации.\n\n2.Президент Российской Федерации прекращает исполнение полномочий досрочно в случае его отставки, стойкой неспособности по состоянию здоровья осуществлять принадлежащие ему полномочия или отрешения от должности. При этом выборы Президента Российской Федерации должны состояться не позднее трех месяцев с момента досрочного прекращения исполнения полномочий.\n\n3.Во всех случаях, когда Президент Российской Федерации не в состоянии выполнять свои обязанности, их временно исполняет Председатель Правительства Российской Федерации. Исполняющий обязанности Президента Российской Федерации не имеет права распускать Государственную Думу, назначать референдум, а также вносить предложения о поправках и пересмотре положений Конституции Российской Федерации.","article_title":"Статья 92","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"204ac567f6569207cc855cc4af0ce7fb4532f0126ecd37d147c60ddfa5674dc3"},{"code_id":"KONST_RF","article_number":"93","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации может быть отрешен от должности, а Президент Российской Федерации, прекративший исполнение своих полномочий, лишен неприкосновенности Советом Федерации только на основании выдвинутого Государственной Думой обвинения в государственной измене или совершении иного тяжкого преступления, подтвержденного заключением Верховного Суда Российской Федерации о наличии в действиях Президента Российской Федерации, как действующего, так и прекратившего исполнение своих полномочий, признаков преступления и заключением Конституционного Суда Российской Федерации о соблюдении установленного порядка выдвижения обвинения.\n\n2.Решение Государственной Думы о выдвижении обвинения и решение Совета Федерации об отрешении Президента Российской Федерации от должности, о лишении неприкосновенности Президента Российской Федерации, прекратившего исполнение своих полномочий, должны быть приняты двумя третями голосов от общего числа соответственно сенаторов Российской Федерации и депутатов Государственной Думы по инициативе не менее одной трети депутатов Государственной Думы и при наличии заключения специальной комиссии, образованной Государственной Думой.\n\n3.Решение Совета Федерации об отрешении Президента Российской Федерации от должности, о лишении неприкосновенности Президента Российской Федерации, прекратившего исполнение своих полномочий, должно быть принято не позднее чем в трехмесячный срок после выдвижения Государственной Думой обвинения против Президента Российской Федерации. Если в этот срок решение Совета Федерации не будет принято, обвинение против Президента Российской Федерации, Президента Российской Федерации, прекратившего исполнение своих полномочий, считается отклоненным.","article_title":"Статья 93","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4de0fb6edc9797770e74ca59903b9c0d65fc4534b569ae67da5728ae7b0b6775"},{"code_id":"KONST_RF","article_number":"94","version_date":"1993-12-12","article_text":"Федеральное Собрание — парламент Российской Федерации — является представительным и законодательным органом Российской Федерации.","article_title":"Статья 94","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d9dcdf0febfa4ee05517d2098ae781e59fe69c828444a98063e1fc38eb234a77"},{"code_id":"KONST_RF","article_number":"95","version_date":"1993-12-12","article_text":"1.Федеральное Собрание состоит из двух палат — Совета Федерации и Государственной Думы.\n\n2.Совет Федерации состоит из сенаторов Российской Федерации.В Совет Федерации входят:\n\nа)по два представителя от каждого субъекта Российской Федерации: по одному от законодательного (представительного) и исполнительного органов государственной власти — на срок полномочий соответствующего органа;\n\nб)Президент Российской Федерации, прекративший исполнение своих полномочий в связи с истечением срока его пребывания в должности или досрочно в случае его отставки, — пожизненно. Президент Российской Федерации, прекративший исполнение своих полномочий в связи с истечением срока его пребывания в должности или досрочно в случае его отставки, вправе отказаться от полномочий сенатора Российской Федерации;\n\nв)не более 30 представителей Российской Федерации, назначаемых Президентом Российской Федерации, из которых не более семи могут быть назначены пожизненно.\n\n3.Общее число сенаторов Российской Федерации определяется исходя из числа представителей от субъектов Российской Федерации, перечисленных в статье 65 Конституции Российской Федерации, и числа лиц, осуществляющих полномочия сенаторов Российской Федерации, указанных в пунктах «б» и «в» части 2 настоящей статьи.\n\n4.Сенатором Российской Федерации может быть гражданин Российской Федерации, достигший 30 лет, постоянно проживающий в Российской Федерации, не имеющий гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Сенаторам Российской Федерации в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации.\n\n5.Представителями Российской Федерации в Совете Федерации, осуществляющими полномочия сенаторов Российской Федерации пожизненно, могут быть назначены граждане, имеющие выдающиеся заслуги перед страной в сфере государственной и общественной деятельности.\n\n6.Представители Российской Федерации в Совете Федерации, за исключением представителей Российской Федерации, осуществляющих полномочия сенаторов Российской Федерации пожизненно, назначаются сроком на шесть лет.\n\n7.Государственная Дума состоит из 450 депутатов.","article_title":"Статья 95","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6f6913855b58760a20d995d9706e151e85e08475b6ea13429adfdf154a199647"},{"code_id":"KONST_RF","article_number":"96","version_date":"1993-12-12","article_text":"1.Государственная Дума избирается сроком напять лет.\n\nРедакция части 1 приведена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 30 декабря 2008 г. № 6-ФКЗ«Об изменении срока полномочий Президента Российской Федерации и Государственной Думы», вступившим в силу со дня его официального опубликования 31 декабря 2008 г.(Российская газета, 2008, 31 декабря). Применяется в отношении Государственной Думы, избранной после вступления в силу названного Закона.\n\n2.Порядок формирования Совета Федерации и порядок выборов депутатов Государственной Думы устанавливаются федеральными законами.","article_title":"Статья 96","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d25b55e735482fff69622e08ecd7cdf2f1127f6440eda0eabe29a4bfb64d05ed"},{"code_id":"KONST_RF","article_number":"97","version_date":"1993-12-12","article_text":"1.Депутатом Государственной Думы может быть избран гражданин Российской Федерации, достигший 21 года и имеющий право участвовать в выборах, постоянно проживающий в Российской Федерации, не имеющий гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Депутатам Государственной Думы в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации.*\n\n2.Одно и то же лицо не может одновременно являться сенатором Российской Федерации и депутатом Государственной Думы. Депутат Государственной Думы не может быть депутатом иных представительных органов государственной власти и органов местного самоуправления.*\n\n3.Депутаты Государственной Думы работают на профессиональной постоянной основе. Депутаты Государственной Думы не могут находиться на государственной службе, заниматься другой оплачиваемой деятельностью, кроме преподавательской, научной и иной творческой деятельности.","article_title":"Статья 97","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a9976d1c69a10710f544f0f5766d46e027214ef7f04b3e762a0e4d76b3046208"},{"code_id":"KONST_RF","article_number":"98","version_date":"1993-12-12","article_text":"1.Сенаторы Российской Федерации и депутаты Государственной Думы обладают неприкосновенностью в течение всего срока их полномочий. Они не могут быть задержаны, арестованы, подвергнуты обыску, кроме случаев задержания на месте преступления, а также подвергнуты личному досмотру, за исключением случаев, когда это предусмотрено федеральным законом для обеспечения безопасности других людей.*\n\n2.Вопрос о лишении неприкосновенности решается по представлению Генерального прокурора Российской Федерации соответствующей палатой Федерального Собрания.","article_title":"Статья 98","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93a2c974d58bc7e0ed22f2317498743fcf9fb44206b53be0b02dc224ef185ef6"},{"code_id":"KONST_RF","article_number":"99","version_date":"1993-12-12","article_text":"1.Федеральное Собрание является постоянно действующим органом.\n\n2.Государственная Дума собирается на первое заседание на тридцатый день после избрания. Президент Российской Федерации может созвать заседание Государственной Думы ранее этого срока.\n\n3.Первое заседание Государственной Думы открывает старейший по возрасту депутат.\n\n4.С момента начала работы Государственной Думы нового созыва полномочия Государственной Думы прежнего созыва прекращаются.","article_title":"Статья 99","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c6e46a71036bcbee5ca4360399b2492003bd4e56c817928961a390e16fa79118"},{"code_id":"NK_RF","article_number":"1","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.07.2006 № 137-ФЗ, от 11.06.2021 № 199-ФЗ)\n\n1) виды налогов и сборов, взимаемых в Российской Федерации; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n2) основания возникновения (изменения, прекращения) и порядок исполнения обязанностей по уплате налогов и сборов; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n3) принципы установления, введения в действие и прекращения действия ранее введенных налогов субъектов Российской Федерации и местных налогов; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2006 № 137-ФЗ)\n\n4) права и обязанности налогоплательщиков, налоговых органов и других участников отношений, регулируемых законодательством о налогах и сборах; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n5) формы и методы налогового контроля; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n6) ответственность за совершение налоговых правонарушений; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n7) порядок обжалования актов налоговых органов и действий (бездействия) их должностных лиц. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nПравоотношения, возникающие в ходе проведения указанных экспериментов, регулируются законодательством о налогах и сборах с учетом особенностей, установленных федеральными законами о проведении экспериментов.\n\nВ период проведения эксперимента, но не позднее чем за шесть месяцев до его окончания Правительство Российской Федерации представляет в Государственную Думу Федерального Собрания Российской Федерации отчет об эффективности (неэффективности) проведенного эксперимента, а также предложения о его продлении, об установлении настоящим Кодексом соответствующего налога, сбора, специального налогового режима либо о прекращении такого эксперимента.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2018 № 425-ФЗ)","article_title":"Статья 1. Законодательство Российской Федерации о налогах и сборах, законодательство субъектов Российской Федерации о налогах и сборах, нормативные правовые акты представительных органов муниципальных образований о налогах и сборах, нормативные правовые акты представительного органа федеральной территории \"Сириус\" о местных налогах и сборах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50fa0b25a90ebe6993519d6a3b33cfab47e8ad1739787cc32db5ddbaf5f2f338"},{"code_id":"NK_RF","article_number":"10","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n1. Порядок привлечения к ответственности и производство по делам о налоговых правонарушениях осуществляются в порядке, установленном главами 14, 15 настоящего Кодекса.\n\n2. Производство по делам о нарушениях законодательства о налогах и сборах, содержащих признаки административного правонарушения или преступления, ведется в порядке, установленном соответственно законодательством Российской Федерации об административных правонарушениях и уголовно-процессуальным законодательством Российской Федерации.","article_title":"Статья 10. Порядок производства по делам о нарушениях законодательства о налогах и сборах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"489778748cd8c16527f27a4108543dcad2df7052b28cf0f7630e85ae0753bab3"},{"code_id":"NK_RF","article_number":"100","version_date":"2000-07-31","article_text":"1. По результатам выездной налоговой проверки в течение двух месяцев со дня составления справки о проведенной выездной налоговой проверке уполномоченными должностными лицами налоговых органов должен быть составлен в установленной форме акт налоговой проверки.\n\nВ случае выявления нарушений законодательства о налогах и сборах в ходе проведения камеральной налоговой проверки должностными лицами налогового органа, проводящими указанную проверку, должен быть составлен акт налоговой проверки по установленной форме в течение 10 дней после окончания камеральной налоговой проверки.\n\nПо результатам выездной налоговой проверки консолидированной группы налогоплательщиков в течение трех месяцев со дня составления справки о проведенной выездной налоговой проверке уполномоченными должностными лицами налоговых органов должен быть составлен в установленной форме акт налоговой проверки. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n2. Акт налоговой проверки подписывается лицами, проводившими соответствующую проверку, и лицом, в отношении которого проводилась эта проверка (его представителем). При проведении налоговой проверки консолидированной группы налогоплательщиков акт налоговой проверки подписывается лицами, проводившими соответствующую проверку, и ответственным участником этой группы (его представителем).\n\nОб отказе лица, в отношении которого проводилась налоговая проверка, или его представителя (ответственного участника консолидированной группы налогоплательщиков) подписать акт делается соответствующая запись в акте налоговой проверки.\n\n(Пункт в редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\n3. В акте налоговой проверки указываются:\n\n1) дата акта налоговой проверки. Под указанной датой понимается дата подписания акта лицами, проводившими эту проверку;\n\n2) полное и сокращенное наименования либо фамилия, имя, отчество проверяемого лица (участников консолидированной группы налогоплательщиков). В случае проведения проверки организации по месту нахождения ее обособленного подразделения помимо наименования организации указываются полное и сокращенное наименования проверяемого обособленного подразделения и место его нахождения; (В редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\n3) фамилии, имена, отчества лиц, проводивших проверку, их должности с указанием наименования налогового органа, который они представляют;\n\n4) дата и номер решения руководителя (заместителя руководителя) налогового органа о проведении выездной налоговой проверки (для выездной налоговой проверки);\n\n5) дата представления в налоговый орган налоговой декларации (расчета) и иных документов (для камеральной налоговой проверки); (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n6) перечень документов, представленных проверяемым лицом в ходе налоговой проверки;\n\n7) период, за который проведена проверка;\n\n8) наименование налога, в отношении которого проводилась налоговая проверка;\n\n9) даты начала и окончания налоговой проверки;\n\n10) адрес места нахождения организации (участников консолидированной группы налогоплательщиков) или места жительства физического лица; (В редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\n11) сведения о мероприятиях налогового контроля, проведенных при осуществлении налоговой проверки;\n\n12) документально подтвержденные факты нарушений законодательства о налогах и сборах, выявленные в ходе проверки, или запись об отсутствии таковых;\n\n13) выводы и предложения проверяющих по устранению выявленных нарушений и ссылки на статьи настоящего Кодекса в случае, если настоящим Кодексом предусмотрена ответственность за данные нарушения законодательства о налогах и сборах.\n\n4. Форма и требования к составлению акта налого\n\nвой проверки устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если лицо, в отношении которого проводилась проверка, или его представитель уклоняются от получения акта налоговой проверки, этот факт отражается в акте налоговой проверки, и акт налоговой проверки направляется по почте заказным письмом по месту нахождения организации (обособленного подразделения) или месту жительства физического лица. В случае направления акта налоговой проверки по почте заказным письмом датой вручения этого акта считается шестой день считая с даты отправки заказного письма.\n\nПри проведении налоговой проверки консолидированной группы налогоплательщиков акт налоговой проверки в течение 10 дней с даты этого акта вручается ответственному участнику консолидированной группы налогоплательщиков в порядке, установленном настоящим пунктом. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\nАкт налоговой проверки направляется иностранной организации (за исключением международной организации, дипломатического представительства, иностранного лица, подлежащего постановке на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса), не осуществляющей деятельность на территории Российской Федерации через обособленное подразделение, по почте заказным письмом по адресу, содержащемуся в Едином государственном реестре налогоплательщиков. Датой вручения этого акта считается двадцатый день, считая с даты отправки заказного письма. (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции  федеральных законов от 03.07.2016 № 244-ФЗ, от 29.05.2024 № 100-ФЗ)\n\nПисьменные возражения по акту налоговой проверки консолидированной группы налогоплательщиков представляются ответственным участником этой группы в течение 30 дней со дня получения указанного акта. При этом ответственный участник консолидированной группы налогоплательщиков вправе приложить к письменным возражениям или в согласованный срок передать в налоговый орган документы (их заверенные копии), подтверждающие обоснованность своих возражений. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 100. Оформление результатов налоговой проверки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1219473fa250174c6de2a2738a71c47b7308941d72b72a1ed4997ab594edfcbf"},{"code_id":"NK_RF","article_number":"100.1","version_date":"2000-07-31","article_text":"1. Дела о выявленных в ходе камеральной или выездной налоговой проверки налоговых правонарушениях рассматриваются в порядке, предусмотренном статьей 101 настоящего Кодекса.\n\n2. Дела о выявленных в ходе иных мероприятий налогового контроля налоговых правонарушениях (за исключением правонарушений, предусмотренных статьями 120, 122 и 123 настоящего Кодекса) рассматриваются в порядке, предусмотренном статьей 1014 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 100.1. Порядок рассмотрения дел о налоговых правонарушениях","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc7c9ee6bee0835ef8beb4e736dab3b9780de8a0ee62f3e97c7adb613154a82d"}]$law7d0047$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
